import calendar
from datetime import date, timedelta

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])
    res: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            res.append((start_date + timedelta(days=i * k)).isoformat())
        return res

    if freq == "WEEKLY":
        days = sorted(_WEEKDAYS[code] for code in parts[2].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        step = 0
        while len(res) < count:
            monday = week0_monday + timedelta(days=step * 7)
            for wd in days:
                cand = monday + timedelta(days=wd)
                if cand >= start_date:
                    res.append(cand.isoformat())
                    if len(res) == count:
                        break
            step += k
        return res

    if freq == "MONTHLY":
        base_months = start_date.year * 12 + (start_date.month - 1)
        step = 0
        if len(parts) == 3:
            d = int(parts[2])
            while len(res) < count:
                y, m0 = divmod(base_months + step, 12)
                mo = m0 + 1
                last_day = calendar.monthrange(y, mo)[1]
                day = last_day if d == -1 else d
                if day <= last_day:
                    cand = date(y, mo, day)
                    if cand >= start_date:
                        res.append(cand.isoformat())
                step += k
        else:
            n = int(parts[2])
            target_wd = _WEEKDAYS[parts[3]]
            while len(res) < count:
                y, m0 = divmod(base_months + step, 12)
                mo = m0 + 1
                first_wd, last_day = calendar.monthrange(y, mo)
                if n == -1:
                    last_wd = (first_wd + last_day - 1) % 7
                    day = last_day - (last_wd - target_wd) % 7
                else:
                    day = 1 + (target_wd - first_wd) % 7 + (n - 1) * 7
                if day <= last_day:
                    cand = date(y, mo, day)
                    if cand >= start_date:
                        res.append(cand.isoformat())
                step += k
        return res

    if freq == "YEARLY":
        mm, dd = (int(x) for x in parts[2].split("-"))
        y = start_date.year
        while len(res) < count:
            if dd <= calendar.monthrange(y, mm)[1]:
                cand = date(y, mm, dd)
                if cand >= start_date:
                    res.append(cand.isoformat())
            y += k
        return res

    raise ValueError(f"Unsupported rule: {rule}")
